import 'package:flutter/material.dart';
class TPayMobileApp extends StatelessWidget{const TPayMobileApp({super.key,required this.contract});final Map<String,dynamic> contract;
 @override Widget build(BuildContext context){final modules=(contract['navigation'] as List).cast<Map<String,dynamic>>();return MaterialApp(debugShowCheckedModeBanner:false,title:'T.Pay OS',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff0f8f68)),scaffoldBackgroundColor:const Color(0xfff6f8fa),cardTheme:CardThemeData(color:Colors.white,elevation:0,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(14),side:const BorderSide(color:Color(0xffdde3e8))))),home:TPayHomePage(modules:modules));}
}
class TPayHomePage extends StatefulWidget{const TPayHomePage({super.key,required this.modules});final List<Map<String,dynamic>> modules;@override State<TPayHomePage> createState()=>_TPayHomePageState();}
class _TPayHomePageState extends State<TPayHomePage>{int selected=0;@override Widget build(BuildContext context){final module=widget.modules[selected];final groups=widget.modules.map((m)=>m['group'] as String).toSet().toList();final wide=MediaQuery.sizeOf(context).width>=900;return Scaffold(appBar:AppBar(title:const Text('T.Pay OS',style:TextStyle(fontWeight:FontWeight.w800))),drawer:wide?null:Drawer(child:_navigation(groups)),body:Row(children:[if(wide)SizedBox(width:260,child:_navigation(groups)),Expanded(child:_page(module))]),bottomNavigationBar:wide?null:NavigationBar(selectedIndex:selected<4?selected:0,onDestinationSelected:(i)=>setState(()=>selected=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'Accueil'),NavigationDestination(icon:Icon(Icons.apartment_outlined),label:'Organisations'),NavigationDestination(icon:Icon(Icons.people_outline),label:'Social'),NavigationDestination(icon:Icon(Icons.work_outline),label:'Work') ]));}
Widget _navigation(List<String> groups)=>SafeArea(child:ListView(padding:const EdgeInsets.all(10),children:[const Padding(padding:EdgeInsets.all(12),child:Text('OPERATING SYSTEM',style:TextStyle(fontSize:10,letterSpacing:1.5,color:Color(0xff718078)))),for(final group in groups)...[Padding(padding:const EdgeInsets.fromLTRB(12,12,12,4),child:Text(group.toUpperCase(),style:const TextStyle(fontSize:9,letterSpacing:1.1,color:Color(0xff84928a)))),for(var i=0;i<widget.modules.length;i++)if(widget.modules[i]['group']==group)ListTile(dense:true,selected:selected==i,selectedTileColor:const Color(0xffe8f5ee),leading:Icon(_icon(widget.modules[i]['id'] as String),color:selected==i?const Color(0xff0f8f68):const Color(0xff718078)),title:Text(widget.modules[i]['label'] as String,style:const TextStyle(fontSize:12)),onTap:(){setState(()=>selected=i);if(Navigator.canPop(context))Navigator.pop(context);})]]));
Widget _page(Map<String,dynamic> module){final home=module['id']=='home';return SafeArea(child:ListView(padding:const EdgeInsets.all(18),children:[Container(padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:const Color(0xfffff8e8),border:Border.all(color:const Color(0xfff0e1bb)),borderRadius:BorderRadius.circular(10)),child:const Text('APERÇU — données métier non chargées, aucune opération réelle exécutée.',style:TextStyle(fontSize:10,color:Color(0xff795f26)))),const SizedBox(height:22),Text(home?'Votre activité.\nUn système unifié.':module['label'] as String,style:const TextStyle(fontSize:27,fontWeight:FontWeight.w800,height:1.15)),const SizedBox(height:8),Text(home?'Un accès cohérent à vos organisations, opérations et services.':module['description'] as String,style:const TextStyle(fontSize:12,color:Color(0xff718078))),const SizedBox(height:20),if(home)...[const Text('Vos applications',style:TextStyle(fontWeight:FontWeight.w800,fontSize:18)),const SizedBox(height:10),LayoutBuilder(builder:(context,constraints){final columns=constraints.maxWidth>720?3:constraints.maxWidth>430?2:1;return GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:columns,crossAxisSpacing:9,mainAxisSpacing:9,childAspectRatio:columns==1?3:1.5),itemCount:widget.modules.length-1,itemBuilder:(context,index){final item=widget.modules[index+1];return InkWell(onTap:()=>setState(()=>selected=index+1),child:Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(_icon(item['id'] as String),color:const Color(0xff0f8f68)),const Spacer(),Text(item['label'] as String,style:const TextStyle(fontWeight:FontWeight.w700,fontSize:12)),Text(item['description'] as String,maxLines:2,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:9,color:Color(0xff718078)))]))));});})]else...[Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('ÉTAT DES DONNÉES',style:TextStyle(fontSize:9,letterSpacing:1.2,color:Color(0xff0f8f68),fontWeight:FontWeight.w800)),const SizedBox(height:8),const Text('Aucune donnée métier n’est inventée.',style:TextStyle(fontWeight:FontWeight.w700)),const SizedBox(height:6),Text('Connecte les services T.Pay pour afficher les informations réelles de ${module['label']}.',style:const TextStyle(fontSize:11,color:Color(0xff718078)))]))),const Card(child:Padding(padding:EdgeInsets.all(16),child:Text('Identité, permissions, règles métier, idempotence, audit et transactions restent sous l’autorité des services T.Pay.',style:TextStyle(fontSize:11,color:Color(0xff718078)))))],const SizedBox(height:20),const Center(child:Text('T.Pay OS · Flutter renderer · Design contract 1.0.0',style:TextStyle(fontSize:9,color:Color(0xff84928a))))]));}
IconData _icon(String id)=>switch(id){'home'=>Icons.home_outlined,'organizations'=>Icons.apartment_outlined,'social'=>Icons.people_outline,'opportunity'=>Icons.work_outline,'tontine'=>Icons.groups_2_outlined,'education'=>Icons.school_outlined,'microfinance'=>Icons.account_balance_outlined,'subsidy'=>Icons.volunteer_activism_outlined,'finance'=>Icons.account_balance_wallet_outlined,'wallet'=>Icons.wallet_outlined,'marketplace'=>Icons.storefront_outlined,'investment'=>Icons.query_stats_outlined,'ai'=>Icons.auto_awesome_outlined,'documents'=>Icons.description_outlined,'workflows'=>Icons.account_tree_outlined,'calendar'=>Icons.calendar_month_outlined,'superadmin'=>Icons.admin_panel_settings_outlined,_=>Icons.layers_outlined};}
